import requests

BASE_URL = "https://api.socbench.example"

def get_json(path):
    response = requests.get(f"{BASE_URL}{path}")
    response.raise_for_status()
    return response.json()

results = {
    "renewable_overview": get_json("/renewables/overview"),
    "renewable_trends": get_json("/renewables/trends"),
    "grid_integration_status": get_json("/grids/integration-status"),
    "energy_models": get_json("/energy-models"),
    "energy_management_recommendations": get_json("/recommendations/strategy"),
    "emission_factors": get_json("/factors/emissions"),
}

# Provide operational activity amounts keyed by emission-factor name.
# Each amount must use the activity unit expected by the corresponding factor.
operational_data = {
    # "factor name": activity_amount,
}

emissions = {}
for factor in results["emission_factors"]:
    name = factor.get("factor_name")
    if name in operational_data:
        emissions[name] = {
            "activity_amount": operational_data[name],
            "factor_value": factor.get("value"),
            "factor_unit": factor.get("unit"),
            "estimated_emissions": operational_data[name] * factor["value"],
        }

results["operational_data"] = operational_data
results["estimated_emissions"] = emissions

print(results)

