import requests

BASE_URL = "https://api.socbench.example"

trends_response = requests.get(f"{BASE_URL}/analytics/recycling-trends")
trends_response.raise_for_status()
trends_data = trends_response.json()

trend_records = trends_data.get("trendData", [])
if not isinstance(trend_records, list):
    raise ValueError("Unexpected recycling trends response")

volumes = [
    record["volumeRecycled"]
    for record in trend_records
    if isinstance(record, dict) and isinstance(record.get("volumeRecycled"), (int, float))
]
average_volume = sum(volumes) / len(volumes) if volumes else 0
threshold = average_volume

deficiencies = [
    record for record in trend_records
    if isinstance(record, dict)
    and isinstance(record.get("volumeRecycled"), (int, float))
    and record["volumeRecycled"] < threshold
]

materials_response = requests.get(f"{BASE_URL}/waste-materials")
materials_response.raise_for_status()
materials = materials_response.json()

material_categories = {}
if isinstance(materials, list):
    for material in materials:
        if isinstance(material, dict):
            category = material.get("composition") or "Uncategorized"
            material_categories.setdefault(category, []).append(material)

alert_response = requests.post(
    f"{BASE_URL}/alerts",
    json={
        "condition": (
            f"Recycling performance below threshold of {threshold:.2f} "
            f"volume units; identified deficient periods: {deficiencies}. "
            f"Available material types categorized by composition: {material_categories}."
        ),
        "notification_method": "email",
        "recipients": ["users"],
    },
)
alert_response.raise_for_status()

